// Emoji stories' generated files (design §5.3, §9, §12), from the hand-kept src/data/emoji-stories/stories.json:
//   src/data/emoji-stories/emoji.json     each emoji used, with its Unicode name, version and subgroup
//   src/data/emoji-stories/daily.json     the Daily schedule, about two years ahead
//   docs/features/emoji-stories/review-sheet.md   the by-eye check of every puzzle (§5.5 check 6)
//
//   node --experimental-strip-types scripts/build-emoji-stories.ts                  write all three
//   node --experimental-strip-types scripts/build-emoji-stories.ts --check          fail if any is out of date
//   node --experimental-strip-types scripts/build-emoji-stories.ts --epoch 2026-12-01   first build only
//
// Unicode's emoji-test.txt 15.1 (free, unicode.org) was downloaded once into <sources>/unicode/emoji-test-15.1.txt,
// where <sources> is found as scripts/bible/paths.py finds it (BIBLE_SOURCES, else sources/ in the site, else
// ../sources), and its SHA-256 is pinned below. --check reads no clock: it re-derives the schedule after the file's
// own frozenThrough up to the file's own length, so it gives the same answer on every day.
import fs from "node:fs";
import path from "node:path";
import { createHash } from "node:crypto";
import { RELAX_ORDER, candidates, dailyPool, extendDays, rulesFor } from "../src/pages/games/emoji-stories/daily-rules.ts";
import type { DailySchedule, EmojiFile, EmojiInfo, Story, StoryFile } from "../src/pages/games/emoji-stories/types.ts";

const SITE = path.resolve(import.meta.dirname, "..");
const DATA = path.join(SITE, "src/data/emoji-stories");
const STORIES = path.join(DATA, "stories.json");
const EMOJI = path.join(DATA, "emoji.json");
const DAILY = path.join(DATA, "daily.json");
const SHEET = path.join(SITE, "docs/features/emoji-stories/review-sheet.md");
const UNICODE_SHA256 = "d876ee249aa28eaa76cfa6dfaa702847a8d13b062aa488d465d0395ee8137ed9";
const DAYS_AHEAD = 730;
const FROZEN_AHEAD = 14;
const DAY_MS = 86_400_000;

function fail(message: string): never {
  console.error(`build-emoji-stories: ${message}`);
  process.exit(1);
}

function sourcesDir(): string {
  if (process.env.BIBLE_SOURCES) return path.resolve(process.env.BIBLE_SOURCES);
  const inside = path.join(SITE, "sources");
  return fs.existsSync(inside) && fs.statSync(inside).isDirectory() ? inside : path.join(SITE, "..", "sources");
}

function readUnicode(): Map<string, EmojiInfo & { status: string }> {
  const file = path.join(sourcesDir(), "unicode", "emoji-test-15.1.txt");
  if (!fs.existsSync(file)) fail(`missing ${file}; download https://unicode.org/Public/emoji/15.1/emoji-test.txt there`);
  const bytes = fs.readFileSync(file);
  const sha = createHash("sha256").update(bytes).digest("hex");
  if (sha !== UNICODE_SHA256) fail(`${file} has SHA-256 ${sha}, expected ${UNICODE_SHA256}; restore the recorded download`);
  const table = new Map<string, EmojiInfo & { status: string }>();
  let subgroup = "";
  for (const line of bytes.toString("utf8").split(/\r?\n/)) {
    if (line.startsWith("# subgroup:")) subgroup = line.slice("# subgroup:".length).trim();
    const match = /^[0-9A-F ]+;\s*([\w-]+)\s*#\s*(\S+)\s+E(\d+\.\d+)\s+(.*)$/.exec(line);
    if (match) table.set(match[2], { status: match[1], name: match[4], version: Number(match[3]), subgroup });
  }
  return table;
}

function emojiFile(stories: readonly Story[], unicode: ReturnType<typeof readUnicode>): EmojiFile {
  const used = [...new Set(stories.flatMap((story) => story.emoji.map(([emoji]) => emoji)))].sort();
  const emoji: Record<string, EmojiInfo> = {};
  for (const char of used) {
    const info = unicode.get(char);
    if (!info) fail(`${JSON.stringify(char)} is not in Unicode's emoji-test.txt; use the fully-qualified form`);
    emoji[char] = { name: info.name, version: info.version, subgroup: info.subgroup };
  }
  return { about: "Generated by scripts/build-emoji-stories.ts from Unicode emoji-test.txt 15.1; do not edit.", unicode: "15.1", emoji };
}

const dateKey = (date: Date): string =>
  `${date.getFullYear()}-${String(date.getMonth() + 1).padStart(2, "0")}-${String(date.getDate()).padStart(2, "0")}`;
const keyDay = (key: string): number => {
  const [year, month, day] = key.split("-").map(Number);
  return Date.UTC(year, month - 1, day) / DAY_MS;
};

function schedule(stories: readonly Story[], previous: DailySchedule | null, check: boolean, epochArgument: string | null): DailySchedule {
  if (epochArgument && !/^\d{4}-\d{2}-\d{2}$/.test(epochArgument)) fail(`--epoch expects YYYY-MM-DD, got ${epochArgument}`);
  if (previous && epochArgument && epochArgument !== previous.epoch) {
    fail(`daily.json already starts on ${previous.epoch}; delete it before the first release to renumber, never after`);
  }
  const epoch = previous?.epoch ?? epochArgument ?? dateKey(new Date());
  const known = new Set(stories.map((story) => story.id));
  const pool = dailyPool(stories);
  const rules = rulesFor(pool, epoch, stories);
  let frozenThrough = 0;
  let length = DAYS_AHEAD;
  if (previous && check) {
    frozenThrough = previous.frozenThrough;
    length = previous.days.length;
  } else if (previous) {
    const today = keyDay(dateKey(new Date())) - keyDay(epoch) + 1;
    frozenThrough = Math.min(previous.days.length, Math.max(previous.frozenThrough, today + FROZEN_AHEAD));
    length = Math.max(previous.days.length, today + DAYS_AHEAD);
  }
  const days = (previous?.days ?? []).slice(0, frozenThrough);
  const unknown = days.filter((id) => !known.has(id));
  if (unknown.length) fail(`daily.json's kept days name stories no longer in stories.json: ${[...new Set(unknown)].join(", ")}; retire them instead`);
  extendDays(rules, pool, days, length);
  return { epoch, frozenThrough, days };
}

/** Days after frozenThrough where a rule gave way, as (puzzle number, rules that gave way). */
function gaveWay(stories: readonly Story[], daily: DailySchedule): string[] {
  const pool = dailyPool(stories);
  const rules = rulesFor(pool, daily.epoch, stories);
  const lines: string[] = [];
  for (let index = daily.frozenThrough; index < daily.days.length; index++) {
    let relaxed = 0;
    while (relaxed < RELAX_ORDER.length && !candidates(rules, pool, daily.days, index, relaxed).some((story) => story.id === daily.days[index])) relaxed++;
    if (relaxed) lines.push(`- #${index + 1}: ${RELAX_ORDER.slice(0, relaxed).join(", ")} gave way`);
  }
  return lines;
}

const PERSON = /^(person|family|hand|body)/;

function reviewSheet(stories: readonly Story[], emoji: EmojiFile, daily: DailySchedule): string {
  const info = (char: string) => emoji.emoji[char];
  const lines = [
    "# Emoji stories — review sheet",
    "",
    "Generated by `scripts/build-emoji-stories.ts`; do not edit. Each emoji's official Unicode name sits beside the passage",
    "word it stands for, so a clue that does not mean what it claims stands out (design §5.5 check 6). **FACE** marks a",
    "face emoji (never a deciding clue, never God or Jesus); **PERSON** marks a person, hand or body emoji (never an adult",
    "standing for God or Jesus; 👶 for the infant Jesus is allowed).",
    "",
    "## Counts",
    "",
    "| | Old Testament | New Testament | All |",
    "|---|---|---|---|",
  ];
  const live = stories.filter((story) => !story.retired);
  for (const tier of [1, 2, 3] as const) {
    const count = (testament?: string) => live.filter((story) => story.tier === tier && (!testament || story.testament === testament)).length;
    lines.push(`| Tier ${tier} | ${count("old")} | ${count("new")} | ${count()} |`);
  }
  lines.push(`| All | ${live.filter((s) => s.testament === "old").length} | ${live.filter((s) => s.testament === "new").length} | ${live.length} |`, "", "## Puzzles", "");
  for (const story of stories) {
    const clues = story.emoji.map(([char, word]) => {
      const { name, subgroup } = info(char);
      const mark = subgroup.startsWith("face-") ? " **FACE**" : PERSON.test(subgroup) ? " **PERSON**" : "";
      return `${char} *${name}* — ${word}${mark}`;
    });
    lines.push(`- **${story.title}** (\`${story.id}\`, ${story.ref}, tier ${story.tier}${story.retired ? ", retired" : ""}): ${clues.join(" · ")}`);
  }
  lines.push("", "## Pairs sharing two or more emoji", "", "Never offered side by side as choices; list a pair a fair player could still mix up under `confusable`.", "");
  for (let i = 0; i < stories.length; i++) {
    for (let j = i + 1; j < stories.length; j++) {
      const a = stories[i], b = stories[j];
      const both = a.emoji.map(([char]) => char).filter((char) => b.emoji.some(([other]) => other === char));
      if (both.length >= 2) lines.push(`- ${a.id} / ${b.id}: ${both.join("")}${a.confusable.includes(b.id) ? " (confusable)" : ""}`);
    }
  }
  const relaxed = gaveWay(stories, daily);
  lines.push("", "## Daily days where a rule gave way", "", ...(relaxed.length ? relaxed : ["None."]), "");
  return lines.join("\n");
}

const readJson = <T>(file: string): T | null => (fs.existsSync(file) ? (JSON.parse(fs.readFileSync(file, "utf8")) as T) : null);
const json = (value: unknown): string => `${JSON.stringify(value, null, 1)}\n`;

function main(): void {
  const args = process.argv.slice(2);
  const check = args.includes("--check");
  const epochAt = args.indexOf("--epoch");
  const stories = (readJson<StoryFile>(STORIES) ?? fail(`missing ${STORIES}`)).stories;
  const emoji = emojiFile(stories, readUnicode());
  const previous = readJson<DailySchedule>(DAILY);
  if (check && !previous) fail("daily.json is missing; run without --check");
  const daily = schedule(stories, previous, check, epochAt >= 0 ? args[epochAt + 1] ?? null : null);
  const outputs: [string, string][] = [
    [EMOJI, json(emoji)],
    [DAILY, `{\n "epoch": ${JSON.stringify(daily.epoch)},\n "frozenThrough": ${daily.frozenThrough},\n "days": [\n${daily.days.map((id) => `  ${JSON.stringify(id)}`).join(",\n")}\n ]\n}\n`],
    [SHEET, reviewSheet(stories, emoji, daily)],
  ];
  if (check) {
    const stale = outputs.filter(([file, text]) => !fs.existsSync(file) || fs.readFileSync(file, "utf8").replace(/\r\n/g, "\n") !== text);
    if (stale.length) fail(`out of date: ${stale.map(([file]) => path.relative(SITE, file)).join(", ")}; run node --experimental-strip-types scripts/build-emoji-stories.ts`);
    console.log("build-emoji-stories: emoji.json, daily.json and the review sheet are up to date");
    return;
  }
  for (const [file, text] of outputs) fs.writeFileSync(file, text);
  console.log(`build-emoji-stories: ${Object.keys(emoji.emoji).length} emoji, ${daily.days.length} days from ${daily.epoch} (kept ${daily.frozenThrough})`);
}

main();
